def clean_display_name(name):
    """Return name with extra whitespace removed and each word capitalized."""
    words = name.split()
    return " ".join(word.capitalize() for word in words)


import unittest


class TestCleanDisplayName(unittest.TestCase):
    def test_capitalizes_each_word(self):
        self.assertEqual(clean_display_name("ada lovelace"), "Ada Lovelace")

    def test_collapses_extra_whitespace(self):
        self.assertEqual(clean_display_name("  ada   lovelace  "), "Ada Lovelace")
